<?php declare(strict_types=1);
$paymentTags=new \Kulturhus\Verein\PaymentTags($db,(string)$_SESSION['actor']);
$tagMessages=isset($nativeAccess)?(new \Kulturhus\Native\Language\Catalog($db,$nativeAccess))->messages():[];
$tagT=static fn(string$s):string=>\Kulturhus\Native\Language\PaymentTagMessages::text($s,$tagMessages);
$tagE=static fn(string$s):string=>e($tagT($s));
try{$tagState=$paymentTags->state($t['id']);}catch(DomainException$failure){?><p class="error" role="alert"><?= $tagE($failure->getMessage()) ?></p><?php return;}
$tagBody=in_array(input($financeMatchSavedPost,'action'),['payment-tags-assign','payment-tags-save'],true)?$financeMatchSavedPost:[];
$tagCompared=($paymentTagsCompared??false)===true;$tagBadShape=false;$tagOriginalChoices=[];
try{if($tagBody)$tagOriginalChoices=\Kulturhus\Verein\Web\PaymentTagForm::choices($tagBody);foreach(array_merge(['tag_version','tag_key','transaction_id'],input($tagBody,'action')==='payment-tags-save'?['tag_name','tag_id','tag_active']:[])as$tagField)if($tagBody)\Kulturhus\Verein\Web\PaymentTagForm::scalar($tagBody,$tagField);}catch(DomainException){$tagBadShape=true;}
$tagCurrentIds=array_column($tagState['tags'],'id');$tagChosen=$tagBody&&input($tagBody,'action')==='payment-tags-assign'?array_keys($tagOriginalChoices):$tagCurrentIds;
$tagRoute=bankTransactionContext($t['id'],$_GET);$tagRoute['_anchor']='payment-tags';
$tagEdited=null;if(input($_GET,'payment_tag')!=='')try{$tagEdited=$paymentTags->tag(input($_GET,'payment_tag'));}catch(DomainException$failure){?><p class="error" role="alert"><?= $tagE($failure->getMessage()) ?></p><?php }
$tagEditing=$tagBody&&input($tagBody,'action')==='payment-tags-save';
$tagEditId=$tagEditing?input($tagBody,'tag_id'):($tagEdited['id']??'');
if($tagCompared&&$tagEditId!=='')try{$tagEdited=$paymentTags->tag($tagEditId);}catch(DomainException){$tagBadShape=true;}
$tagCatalogueVersion=$tagEditing&&!$tagCompared?input($tagBody,'tag_version'):(string)($tagEdited['version']??0);
$tagCatalogueOriginal=is_string($tagBody['tag_catalogue']??null)?$tagBody['tag_catalogue']:json_encode($tagState['catalogue'],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
?>
<link rel="stylesheet" href="payment-tags.css?v=1">
<section class="card payment-tags" id="payment-tags" data-payment-tags>
<h2><?= $tagE('Zahlungstags') ?></h2><p><?= $tagE('Tags kennzeichnen die gesamte Zahlung. Beträge, Belegzuordnungen und Zahlungsfreigaben bleiben erhalten.') ?></p>
<?php if(!$tagState['available']): ?><p class="notice"><?= $tagE('Zahlungstags benötigen die vollständige Paketaktualisierung.') ?></p><?php else: ?>
<div data-current-payment-tags><h3><?= $tagE('Aktuell gespeicherte Auswahl') ?></h3><ul><?php foreach($tagState['tags']as$tagItem): ?><li><?= e($tagItem['name']) ?><?php if(!(int)$tagItem['active']): ?> · <?= $tagE('Inaktiv') ?><?php endif ?></li><?php endforeach ?></ul><?php if(!$tagState['tags']): ?><p><?= $tagE('Keine Zahlungstags zugeordnet.') ?></p><?php endif ?></div>
<?php if(input($_GET,'tag_receipt')!==''):try{$tagReceipt=$paymentTags->receipt(input($_GET,'tag_receipt'),$t['id']);$tagFirst=json_decode($tagReceipt['next_snapshot'],true,128,JSON_THROW_ON_ERROR); ?><section class="notice" data-tag-first><h3><?= $tagE('Gespeichertes Ergebnis') ?></h3><p><?= e($tagReceipt['happened_at'].' · '.$tagReceipt['actor_id'].' · '.$tagReceipt['result_version']) ?></p><p data-tag-first-name><?= e(isset($tagFirst['name'])?$tagFirst['name']:implode(', ',array_column($tagFirst['tags']??[],'name'))) ?></p><details><summary><?= $tagE('Vollständige ursprüngliche Angaben') ?></summary><pre><?= e(json_encode($tagFirst,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR)) ?></pre></details><p><?= $tagE('Der heutige Stand steht separat oben. Er kann inzwischen weiterbearbeitet worden sein.') ?></p></section><?php }catch(DomainException$failure){?><p class="error" role="alert"><?= $tagE($failure->getMessage()) ?></p><?php }endif ?>
<?php if($tagBody): ?><details class="notice" open data-tag-original><summary><?= $tagE('Angaben') ?></summary><pre><?= e(json_encode(array_diff_key($tagBody,['csrf'=>true]),JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR)) ?></pre><?php if($tagCompared): ?><p role="status"><?= $tagE('Aktuellen Stand übernommen. Auswahl und Namen prüfen; erst erneutes Speichern ändert die Tags.') ?></p><?php endif ?></details><?php endif ?>
<?php if($tagState['inherited']): ?><p><?= $tagE('Tags an der ursprünglichen Zahlung bearbeiten. Die Gegenbuchung übernimmt diese Auswahl.') ?></p><a class="btn btn-outline theme-secondary" href="<?= e(url(bankTransactionContext($tagState['transaction_id'],$_GET)+['_anchor'=>'payment-tags'])) ?>"><?= $tagE('Ursprüngliche Zahlung öffnen') ?></a>
<?php elseif($finance->canWrite()): ?>
<form method="post" data-payment-tags-assign>
<?= hidden('tag_catalogue',$tagCatalogueOriginal).csrf().hidden('action','payment-tags-assign').hidden('transaction_id',$t['id']).hidden('tag_version',$tagBody&&input($tagBody,'action')==='payment-tags-assign'&&!$tagCompared?input($tagBody,'tag_version'):(string)$tagState['version']).hidden('tag_key',$tagBody&&input($tagBody,'action')==='payment-tags-assign'&&!$tagCompared?input($tagBody,'tag_key'):bin2hex(random_bytes(16))) ?>
<fieldset <?= $tagBadShape?'disabled':'' ?>><legend><?= $tagE('Zahlungstags auswählen') ?></legend><p><?= $tagE('Höchstens 20 Tags. Alle Häkchen entfernen, um die Auswahl bewusst zu leeren.') ?></p>
<?php foreach($tagState['catalogue']as$tagItem):$tagChecked=in_array($tagItem['id'],$tagChosen,true);if(!(int)$tagItem['active']&&!$tagChecked&&!in_array($tagItem['id'],$tagCurrentIds,true))continue;$tagChoiceVersion=$tagBody&&!$tagCompared&&isset($tagOriginalChoices[$tagItem['id']])?$tagOriginalChoices[$tagItem['id']]:(int)$tagItem['version']; ?>
<label class="payment-tag-choice"><input class="check" type="checkbox" name="tag_choices[<?= e($tagItem['id']) ?>]" value="<?= $tagChoiceVersion ?>" <?= $tagChecked?'checked':'' ?>><span><?= e($tagItem['name']) ?><?php if(!(int)$tagItem['active']): ?> · <?= $tagE('Inaktiv') ?><?php endif ?></span></label><?php endforeach ?>
<div class="actions"><button class="btn btn-solid theme-primary"><?= $tagE('Tag-Auswahl speichern') ?></button><?php if($tagBody&&input($tagBody,'action')==='payment-tags-assign'): ?><button class="btn btn-outline theme-secondary" name="tag_move" value="compare" formnovalidate><?= $tagE('Aktuellen Stand übernehmen') ?></button><?php endif ?></div></fieldset></form>
<?php endif ?>
<?php if($finance->canWrite()): ?>
<details <?= $tagEditing||$tagEdited?'open':'' ?> data-tag-catalogue><summary><?= $tagE('Tags anlegen und verwalten') ?></summary><p><?= $tagE('Umbenennen gilt für bestehende Zuordnungen. Inaktive Tags bleiben an bisherigen Zahlungen und in Berichten sichtbar.') ?></p>
<ul><?php foreach($tagState['catalogue']as$tagItem): ?><li><a href="<?= e(url($tagRoute+['payment_tag'=>$tagItem['id']])) ?>"><?= e($tagItem['name']) ?></a><?php if(!(int)$tagItem['active']): ?> · <?= $tagE('Inaktiv') ?><?php endif ?></li><?php endforeach ?></ul>
<a class="btn btn-outline theme-secondary" href="<?= e(url($tagRoute)) ?>"><?= $tagE('Neuen Zahlungstag anlegen') ?></a>
<form method="post" data-payment-tag-save><?= hidden('tag_catalogue',$tagCatalogueOriginal).csrf().hidden('action','payment-tags-save').hidden('transaction_id',$t['id']).hidden('tag_id',$tagEditId).hidden('tag_version',$tagCatalogueVersion).hidden('tag_key',$tagEditing&&!$tagCompared?input($tagBody,'tag_key'):bin2hex(random_bytes(16))) ?>
<fieldset <?= $tagBadShape?'disabled':'' ?>><legend><?= $tagE($tagEditId!==''?'Zahlungstag bearbeiten':'Neuer Zahlungstag') ?></legend><label><?= $tagE('Tagname') ?><input class="form-control" name="tag_name" maxlength="80" required value="<?= e($tagEditing?input($tagBody,'tag_name'):($tagEdited['name']??'')) ?>"></label><label><?= $tagE('Verwendung') ?><select class="form-control" name="tag_active"><option value="1" <?= ($tagEditing?input($tagBody,'tag_active'):(string)($tagEdited['active']??1))==='1'?'selected':'' ?>><?= $tagE('Aktiv') ?></option><option value="0" <?= ($tagEditing?input($tagBody,'tag_active'):(string)($tagEdited['active']??1))==='0'?'selected':'' ?>><?= $tagE('Inaktiv') ?></option></select></label>
<div class="actions"><button class="btn btn-solid theme-primary"><?= $tagE('Zahlungstag speichern') ?></button><?php if($tagEditing): ?><button class="btn btn-outline theme-secondary" name="tag_move" value="compare" formnovalidate><?= $tagE('Aktuellen Stand übernehmen') ?></button><?php endif ?></div></fieldset></form></details>
<?php endif ?>
<?php if($tagBadShape): ?><p class="error" role="alert"><?= $tagE('Diese Eingabeform kann hier nicht bearbeitet werden. Angaben sichern und die Zahlung bewusst neu öffnen.') ?></p><a class="btn btn-outline theme-secondary" href="<?= e(url($tagRoute)) ?>"><?= $tagE('Zahlung neu öffnen') ?></a><?php endif ?>
<details data-payment-tag-history><summary><?= $tagE('Verlauf der Tag-Zuordnung') ?></summary><?php foreach($paymentTags->history('transaction',$t['id'])as$tagEvent): ?><article><p><?= e($tagEvent['happened_at'].' · '.$tagEvent['actor_id'].' · '.$tagEvent['source_version'].' → '.$tagEvent['result_version']) ?></p><pre><?= e(json_encode(['previous'=>json_decode($tagEvent['previous_snapshot'],true,128,JSON_THROW_ON_ERROR),'saved'=>json_decode($tagEvent['next_snapshot'],true,128,JSON_THROW_ON_ERROR)],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR)) ?></pre></article><?php endforeach ?></details>
<?php if($tagEdited): ?><details data-payment-tag-catalogue-history><summary><?= $tagE('Verlauf des Zahlungstags') ?></summary><?php foreach($paymentTags->history('catalogue',$tagEdited['id'])as$tagEvent): ?><article><p><?= e($tagEvent['happened_at'].' · '.$tagEvent['actor_id']) ?></p><pre><?= e($tagEvent['previous_snapshot']."\n".$tagEvent['next_snapshot']) ?></pre></article><?php endforeach ?></details><?php endif ?>
<?php endif ?></section>
